/** 按数据集取字段（未登记返回空数组） */
export function voFields(vo: string): VoField[] {
  return VO_SPEC[vo]?.fields ?? [];
}
/** 按数据集 + 字段英文名取字段 */
export function voField(vo: string, code: string): VoField | undefined {
  return voFields(vo).find((f) => f.code === code);
}
/** 必填字段英文名集合（规范"必填=是"） */
export function voRequiredCodes(vo: string): string[] {
  return voFields(vo).filter((f) => f.required).map((f) => f.code);
}
/** 附件采集项（AttachmentItemVO：35 类，含 5 类陕西必传） */
export const ATTACHMENT_ITEMS = VO_SPEC.AttachmentItemVO!.fields;
/** 附件集结构（AttachmentSetVO）字段：GUID / 关联数据集标识 / 数量 / 名称 / 类型 / 文件名 / URL */
export const ATTACHMENT_SET = VO_SPEC.AttachmentSetVO!.fields;
